// The list of the events of the guild chat that scripts/gen-features.ts writes (#426).
import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import {
  generateChatEvents,
  CHAT_EVENTS_DIR,
  CHAT_EVENTS_FILE,
  renderChatEvents,
  scanChatEvents,
} from '../../scripts/gen-features.ts';

describe('the list of the events of the guild chat (#426)', () => {
  let dir: string;
  const HEADER =
    '// Generated by scripts/gen-features.ts; not checked in, do not edit.\n';
  const write = (file: string, source = 'export const chatEvents = [];\n') => {
    mkdirSync(path.dirname(path.join(dir, file)), { recursive: true });
    writeFileSync(path.join(dir, file), source);
  };

  beforeEach(() => {
    dir = path.join(mkdtempSync(path.join(tmpdir(), 'nova-')), 'chat-events');
  });
  afterEach(() => rmSync(path.dirname(dir), { recursive: true, force: true }));

  it('is written before the tests run', () => {
    expect(
      readFileSync(path.join(CHAT_EVENTS_DIR, CHAT_EVENTS_FILE), 'utf8'),
    ).toBe(renderChatEvents(scanChatEvents(CHAT_EVENTS_DIR)));
  });

  it('is empty but valid for an empty or missing folder', () => {
    expect(scanChatEvents(dir)).toEqual([]);
    expect(generateChatEvents(dir)).toBe(true);
    expect(readFileSync(path.join(dir, CHAT_EVENTS_FILE), 'utf8')).toBe(
      `${HEADER}\nexport const CHAT_EVENT_LISTS = [] as const;\n`,
    );
  });

  it('imports every file that exports chatEvents, sorted, and writes only a change', () => {
    write('rank.ts');
    write('attack.ts');
    write('other.ts', 'export const other = 1;\n');
    write('attack.test.ts');
    write(CHAT_EVENTS_FILE);
    write('x.ts', 'export const mychatEvents = [];\n');
    expect(scanChatEvents(dir)).toEqual(['attack.ts', 'rank.ts']);
    expect(generateChatEvents(dir)).toBe(true);
    expect(generateChatEvents(dir)).toBe(false);
    expect(readFileSync(path.join(dir, CHAT_EVENTS_FILE), 'utf8')).toBe(
      [
        HEADER,
        "import { chatEvents as feature_attack } from './attack.ts';",
        "import { chatEvents as feature_rank } from './rank.ts';",
        '',
        'export const CHAT_EVENT_LISTS = [',
        "  ['attack', feature_attack],",
        "  ['rank', feature_rank],",
        '] as const;',
        '',
      ].join('\n'),
    );
  });
});
